SELECT jsonb_build_object('circuits',(SELECT jsonb_agg(to_jsonb(g)||jsonb_build_object('legacy_tag',a.tag)) FROM tb_agregadores g LEFT JOIN tb_agrega_eventos a ON a.id_agrega_evento=g.id_agrega_evento_legado WHERE g.agregador_tag IN ('live-run-xp','estacoes')),'foreignKeys',(SELECT jsonb_agg(jsonb_build_object('table',conrelid::regclass::text,'column',a.attname)) FROM pg_constraint c JOIN pg_attribute a ON a.attrelid=c.conrelid AND a.attnum=c.conkey[1] WHERE c.contype='f' AND c.confrelid='tb_evento_corridas'::regclass AND array_length(c.conkey,1)=1),'locality',(SELECT jsonb_agg(to_jsonb(c)) FROM tb_cidades c WHERE nome_cidade ILIKE 'Pinhais'),'localityFn',(SELECT pg_get_functiondef(oid) FROM pg_proc WHERE proname='preencher_id_localidade_evento' LIMIT 1),'reviewChecks',(SELECT jsonb_agg(pg_get_constraintdef(oid)) FROM pg_constraint WHERE conrelid='tb_evento_fatos_revisao'::regclass))::text payload
